struct Ring {
  std::vector<int> buf;
  std::size_t mask;
  explicit Ring(std::size_t cap)
    : buf(cap), mask(cap - 1) {}
  int& slot(std::size_t i) {
    return buf[i & mask];  // was i % cap
  }
};
